#!/usr/bin/env python3
"""Draws the flat SVG illustrations in public/img/city (original artwork for this project).
Run once: python3 scripts/draw-city-icons.py"""
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / 'public' / 'img' / 'city'
OUT.mkdir(parents=True, exist_ok=True)

SKY = '<rect width="64" height="64" rx="8" fill="#cfe8ff"/>'
GROUND = lambda c='#9aa5b1', y=44: f'<rect x="0" y="{y}" width="64" height="{64 - y}" fill="{c}"/>'
ROAD = lambda y=40: f'<rect x="0" y="{y}" width="64" height="{64 - y}" fill="#4a4e57"/><rect x="0" y="{y + 10}" width="64" height="2" fill="#ffd54a" stroke-dasharray="6 4" stroke="#ffd54a"/>'
BUILDING = lambda x, y, w, h, c: f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{c}"/>' + ''.join(
    f'<rect x="{x + 3 + i * 6}" y="{y + 4 + j * 8}" width="3" height="4" fill="#fff3b0"/>' for i in range((w - 3) // 6) for j in range((h - 6) // 8))

ICONS = {
    'apartment-building': SKY + GROUND() + BUILDING(8, 8, 22, 36, '#c97b63') + BUILDING(34, 16, 22, 28, '#8fa3bf') + '<rect x="16" y="36" width="6" height="8" fill="#5a2d1a"/>',
    'crosswalk': SKY + ROAD(20) + ''.join(f'<rect x="{6 + i * 12}" y="26" width="7" height="30" fill="#fff"/>' for i in range(5)) + '<rect x="0" y="30" width="64" height="0" fill="none"/>' + '<circle cx="32" cy="14" r="5" fill="#f5c6a5"/><rect x="28" y="18" width="8" height="12" rx="2" fill="#2b3a67"/>',
    'streetlight': SKY + GROUND('#7c8a99', 50) + '<rect x="14" y="14" width="4" height="36" fill="#333"/><path d="M16 14 Q16 8 30 8 L40 8" stroke="#333" stroke-width="4" fill="none"/><rect x="36" y="6" width="12" height="6" rx="2" fill="#555"/><ellipse cx="42" cy="14" rx="8" ry="4" fill="#fff59d" opacity=".8"/><path d="M30 14 L54 14 L58 40 L26 40Z" fill="#fff59d" opacity=".35"/>',
    'street-sign': SKY + GROUND() + '<rect x="30" y="12" width="4" height="34" fill="#555"/><rect x="10" y="10" width="44" height="12" rx="1" fill="#1b5e20"/><text x="32" y="19" font-family="sans-serif" font-size="7" font-weight="bold" fill="#fff" text-anchor="middle">WALL ST</text><rect x="16" y="24" width="32" height="10" rx="1" fill="#1b5e20"/><text x="32" y="31.5" font-family="sans-serif" font-size="6" font-weight="bold" fill="#fff" text-anchor="middle">5th AVE</text>',
    'sidewalk': SKY + ROAD(44) + '<rect x="0" y="30" width="64" height="14" fill="#c8ccd2"/>' + ''.join(f'<line x1="{i * 13}" y1="30" x2="{i * 13}" y2="44" stroke="#9aa0a8"/>' for i in range(6)) + '<rect x="0" y="43" width="64" height="2" fill="#7c8a99"/><circle cx="20" cy="22" r="4" fill="#f5c6a5"/><rect x="17" y="25" width="6" height="9" rx="2" fill="#d62828"/><rect x="18" y="34" width="2" height="6" fill="#222"/><rect x="21" y="34" width="2" height="6" fill="#222"/>',
    'bike-lane': SKY + '<rect x="0" y="10" width="64" height="54" fill="#4a4e57"/><rect x="8" y="10" width="26" height="54" fill="#2e7d32"/><rect x="34" y="10" width="2" height="54" fill="#fff"/><rect x="6" y="10" width="2" height="54" fill="#fff"/><circle cx="14" cy="46" r="5" stroke="#fff" stroke-width="2" fill="none"/><circle cx="28" cy="46" r="5" stroke="#fff" stroke-width="2" fill="none"/><path d="M14 46 L19 36 L26 36 L28 46 M19 36 L23 46 L14 46" stroke="#fff" stroke-width="2" fill="none"/>',
    'fountain': SKY + GROUND('#a8b5a0') + '<ellipse cx="32" cy="46" rx="24" ry="6" fill="#4d96ff"/><ellipse cx="32" cy="44" rx="24" ry="6" fill="#8ecae6" stroke="#7c8a99"/><rect x="28" y="28" width="8" height="16" fill="#cfd8dc"/><ellipse cx="32" cy="28" rx="10" ry="3" fill="#cfd8dc"/><path d="M32 12 Q22 20 20 30 M32 12 Q42 20 44 30 M32 12 L32 26" stroke="#8ecae6" stroke-width="3" fill="none" stroke-linecap="round"/><circle cx="32" cy="11" r="3" fill="#8ecae6"/>',
    'tunnel': SKY + '<rect x="0" y="0" width="64" height="64" rx="8" fill="#6b8e5a"/><path d="M8 58 L8 30 A24 24 0 0 1 56 30 L56 58Z" fill="#8d6e63"/><path d="M14 58 L14 32 A18 18 0 0 1 50 32 L50 58Z" fill="#222"/><rect x="14" y="50" width="36" height="8" fill="#4a4e57"/><rect x="31" y="50" width="2" height="8" fill="#ffd54a"/><circle cx="32" cy="34" r="4" fill="#fff59d"/>',
    'intersection': '<rect width="64" height="64" rx="8" fill="#7cb342"/><rect x="22" y="0" width="20" height="64" fill="#4a4e57"/><rect x="0" y="22" width="64" height="20" fill="#4a4e57"/><rect x="31" y="0" width="2" height="20" fill="#ffd54a"/><rect x="31" y="44" width="2" height="20" fill="#ffd54a"/><rect x="0" y="31" width="20" height="2" fill="#ffd54a"/><rect x="44" y="31" width="20" height="2" fill="#ffd54a"/>' + ''.join(f'<rect x="{24 + i * 4}" y="19" width="2" height="3" fill="#fff"/><rect x="{24 + i * 4}" y="42" width="2" height="3" fill="#fff"/>' for i in range(5)) + '<rect x="26" y="8" width="6" height="10" rx="1" fill="#e63946"/><rect x="34" y="46" width="6" height="10" rx="1" fill="#4d96ff"/>',
    'bridge': SKY + '<rect x="0" y="44" width="64" height="20" fill="#4d96ff"/><path d="M4 40 Q32 8 60 40" stroke="#555" stroke-width="4" fill="none"/><rect x="0" y="38" width="64" height="5" fill="#777"/>' + ''.join(f'<line x1="{x}" y1="{40 - (28 - abs(32 - x)) * 0.9}" x2="{x}" y2="38" stroke="#555" stroke-width="1.5"/>' for x in range(10, 56, 6)) + '<rect x="6" y="36" width="4" height="22" fill="#666"/><rect x="54" y="36" width="4" height="22" fill="#666"/>',
    'bench': SKY + GROUND('#7cb342', 46) + '<rect x="8" y="30" width="48" height="5" rx="1" fill="#8d5524"/><rect x="8" y="22" width="48" height="4" rx="1" fill="#8d5524"/><rect x="8" y="16" width="48" height="4" rx="1" fill="#8d5524"/><rect x="12" y="35" width="3" height="14" fill="#333"/><rect x="49" y="35" width="3" height="14" fill="#333"/><rect x="10" y="14" width="3" height="21" fill="#333"/><rect x="51" y="14" width="3" height="21" fill="#333"/><circle cx="50" cy="10" r="6" fill="#4caf50"/>',
    'trash-can': SKY + GROUND('#c8ccd2', 50) + '<rect x="20" y="18" width="24" height="32" rx="3" fill="#2e7d32"/><rect x="17" y="14" width="30" height="5" rx="2" fill="#1b5e20"/><rect x="28" y="10" width="8" height="4" rx="1" fill="#1b5e20"/>' + ''.join(f'<rect x="{24 + i * 6}" y="24" width="2" height="20" fill="#1b5e20"/>' for i in range(3)) + '<path d="M40 10 Q46 6 46 12" stroke="#fff" stroke-width="2" fill="none"/>',
    'statue': SKY + GROUND('#a8b5a0') + '<rect x="18" y="34" width="28" height="10" fill="#9e9e9e"/><rect x="22" y="30" width="20" height="4" fill="#bdbdbd"/><path d="M26 30 L26 22 Q32 14 40 20 L44 26 L42 30Z" fill="#78909c"/><circle cx="36" cy="14" r="3.5" fill="#78909c"/><rect x="34" y="17" width="4" height="8" fill="#78909c"/><path d="M38 18 L46 12" stroke="#78909c" stroke-width="2.5" stroke-linecap="round"/><rect x="28" y="28" width="2" height="4" fill="#78909c"/><rect x="40" y="28" width="2" height="4" fill="#78909c"/>',
    'traffic-lights': SKY + GROUND('#7c8a99', 54) + '<rect x="30" y="40" width="4" height="14" fill="#333"/><rect x="22" y="6" width="20" height="36" rx="4" fill="#333"/><circle cx="32" cy="14" r="5" fill="#e63946"/><circle cx="32" cy="24" r="5" fill="#ffd54a"/><circle cx="32" cy="34" r="5" fill="#4caf50"/>',
}

for name, body in ICONS.items():
    svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64">{body}</svg>'
    (OUT / f'{name}.svg').write_text(svg)
print(f'wrote {len(ICONS)} icons to {OUT}')
